mapper.select:
select sec.Sec_Name as secName, sec.Sec_Code as secCode, c1.c_name as crCNameOne, c2.c_name as crCNameTwo, c3.c_name as crCNameThree,
mn.* from CalibrationReport mn left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join sys_company c1 on c1.c_id=mn.Cr_C_Id_One left join sys_company c2 on c2.c_id=mn.Cr_C_Id_two left join sys_company c3 on c3.c_id=mn.Cr_C_Id_three
where 1=1
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time desc
